// Improved application with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Sanitize against NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging middleware (for debugging/security monitoring)
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any were expected
    if (Object.keys(req.query).length > 0) {
      return res.status(400).json({
        error: 'Bad Request',
        message: 'Health endpoint does not accept query parameters'
      });
    }

    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      service: 'user-service'
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to process health check request'
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Validate limit parameter
    let parsedLimit = 10; // default
    if (limit !== undefined) {
      parsedLimit = parseInt(limit, 10);
      if (isNaN(parsedLimit) || parsedLimit <= 0 || parsedLimit > 100) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Limit must be a positive integer between 1 and 100'
        });
      }
    }

    // Validate offset parameter
    let parsedOffset = 0; // default
    if (offset !== undefined) {
      parsedOffset = parseInt(offset, 10);
      if (isNaN(parsedOffset) || parsedOffset < 0) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Offset must be a non-negative integer'
        });
      }
    }

    // If search parameter exists, validate it
    if (search !== undefined) {
      if (typeof search !== 'string' || search.trim().length === 0) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Search parameter must be a non-empty string'
        });
      }

      // Additional validation: prevent excessively long search strings
      if (search.length > 50) {
        return res.status(400).json({
          error: 'Bad Request',
          message: 'Search parameter too long (max 50 characters)'
        });
      }
    }

    // Simulated database query with validated parameters
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    // Prepare response
    const response = {
      data: paginatedUsers,
      pagination: {
        limit: parsedLimit,
        offset: parsedOffset,
        total: users.length,
        hasMore: parsedOffset + parsedLimit < users.length
      }
    };

    // Add search info if applicable
    if (search) {
      response.search = { term: search.trim() };
    }

    res.json(response);

  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal Server Error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', {
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    method: req.method,
    path: req.path,
    ip: req.ip
  });

  // Determine status code
  const statusCode = err.status || 500;

  // Don't leak stack traces in production
  const response = {
    error: err.message || 'Internal Server Error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  };

  res.status(statusCode).json(response);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throw an error or do other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception thrown', err);
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server };

