// Test file demonstrating validation and error handling
const request = require('supertest');
const { app } = require('./app');

describe('Security and Validation Tests', () => {
  // Test health endpoint
  describe('GET /health', () => {
    it('should return 200 OK', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('status', 'ok');
      expect(response.body).toHaveProperty('timestamp');
    });

    it('should reject query parameters', async () => {
      const response = await request(app)
        .get('/health')
        .query({ invalid: 'param' });
      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Bad Request');
    });
  });

  // Test users endpoint validation
  describe('GET /users', () => {
    it('should return users with default pagination', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('data');
      expect(Array.isArray(response.body.data)).toBe(true);
      expect(response.body.data.length).toBe(2); // default limit is 10 but we only have 2 users
    });

    it('should validate limit parameter', async () => {
      // Test invalid limit (negative)
      let response = await request(app).get('/users?limit=-1');
      expect(response.status).toBe(400);

      // Test invalid limit (not a number)
      response = await request(app).get('/users?limit=abc');
      expect(response.status).toBe(400);

      // Test limit too high
      response = await request(app).get('/users?limit=101');
      expect(response.status).toBe(400);

      // Test valid limit
      response = await request(app).get('/users?limit=1');
      expect(response.status).toBe(200);
      expect(response.body.data.length).toBe(1);
    });

    it('should validate offset parameter', async () => {
      // Test invalid offset (negative)
      let response = await request(app).get('/users?offset=-1');
      expect(response.status).toBe(400);

      // Test invalid offset (not a number)
      response = await request(app).get('/users?offset=xyz');
      expect(response.status).toBe(400);

      // Test valid offset
      response = await request(app).get('/users?offset=1');
      expect(response.status).toBe(200);
    });

    it('should validate search parameter', async () => {
      // Test invalid search (not a string)
      let response = await request(app).get('/users?search=123');
      // Note: This would actually be converted to string by Express, so we test empty string

      // Test empty search
      response = await request(app).get('/users?search=');
      expect(response.status).toBe(400);

      // Test search too long
      response = await request(app).get(`/users?search=${'a'.repeat(51)}`);
      expect(response.status).toBe(400);
    });

    it('should handle valid requests with search', async () => {
      const response = await request(app).get('/users?search=Ali&limit=10');
      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('search');
    });
  });

  // Test 404 handling
  describe('404 Handling', () => {
    it('should return 404 for undefined routes', async () => {
      const response = await request(app).get('/undefined-route');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not Found');
    });
  });

  // Test rate limiting (basic check)
  describe('Rate Limiting', () => {
    it('should have rate limiting headers', async () => {
      const response = await request(app).get('/health');
      // Note: Actual rate limiting would require multiple requests in quick succession
      // This just checks that the middleware is applied
      expect(response.headers).toHaveProperty('x-ratelimit-limit');
    });
  });
});

