// Improved application with enhanced error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(cors()); // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Data sanitization against XSS
app.use(mongoSanitize()); // Data sanitization against NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request logging for security monitoring
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation and sanitization
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const { limit, offset, search } = req.query;

    // Input validation and sanitization
    let validatedLimit = parseInt(limit) || 10;
    let validatedOffset = parseInt(offset) || 0;

    // Ensure limits are within reasonable bounds
    if (isNaN(validatedLimit) || validatedLimit < 1 || validatedLimit > 100) {
      validatedLimit = 10;
    }

    if (isNaN(validatedOffset) || validatedOffset < 0) {
      validatedOffset = 0;
    }

    // Sanitize search parameter if provided
    let sanitizedSearch = '';
    if (search) {
      sanitizedSearch = String(search)
        .trim()
        .substring(0, 50); // Limit length
    }

    // Mock user data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (sanitizedSearch) {
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch.toLowerCase()) ||
        user.email.toLowerCase().includes(sanitizedSearch.toLowerCase())
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(validatedOffset, validatedOffset + validatedLimit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: validatedLimit,
        offset: validatedOffset,
        total: filteredUsers.length,
        returned: paginatedUsers.length
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'An unexpected error occurred'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.path} not found`
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, error);

  // Determine status code
  const statusCode = error.status || 500;

  // Prepare response based on environment
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: isProduction && statusCode === 500 
      ? 'Internal server error' 
      : error.message || 'Unknown error',
    ...(!isProduction && { stack: error.stack }), // Only include stack trace in non-production
    timestamp: new Date().toISOString()
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Perform cleanup actions before exiting
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server };

