// Basic tests to demonstrate security features
const request = require('supertest');
const { app } = require('./app');

describe('Security Features Test', () => {
  let server;

  beforeAll(() => {
    // Create a test server on a random port
    server = app.listen(0);
  });

  afterAll(() => {
    server.close();
  });

  test('Health endpoint returns correct format', async () => {
    const response = await request(server)
      .get('/health')
      .expect('Content-Type', /json/)
      .expect(200);

    expect(response.body).toHaveProperty('status', 'ok');
    expect(response.body).toHaveProperty('timestamp');
  });

  test('Users endpoint validates limit parameter', async () => {
    // Test with valid limit
    let response = await request(server)
      .get('/users?limit=5')
      .expect(200);

    expect(response.body.pagination.limit).toBe(5);
    expect(response.body.data.length).toBeLessThanOrEqual(5);

    // Test with invalid limit (too high) - should be capped
    response = await request(server)
      .get('/users?limit=200')
      .expect(200);

    expect(response.body.pagination.limit).toBe(100); // Max limit

    // Test with invalid limit (negative) - should default
    response = await request(server)
      .get('/users?limit=-5')
      .expect(200);

    expect(response.body.pagination.limit).toBe(10); // Default limit

    // Test with non-numeric limit - should default
    response = await request(server)
      .get('/users?limit=abc')
      .expect(200);

    expect(response.body.pagination.limit).toBe(10); // Default limit
  });

  test('Users endpoint validates offset parameter', async () => {
    // Test with valid offset
    let response = await request(server)
      .get('/users?offset=2')
      .expect(200);

    expect(response.body.pagination.offset).toBe(2);

    // Test with invalid offset (negative) - should default
    response = await request(server)
      .get('/users?offset=-5')
      .expect(200);

    expect(response.body.pagination.offset).toBe(0); // Default offset

    // Test with non-numeric offset - should default
    response = await request(server)
      .get('/users?offset=xyz')
      .expect(200);

    expect(response.body.pagination.offset).toBe(0); // Default offset
  });

  test('Users endpoint sanitizes search parameter', async () => {
    // Test normal search
    let response = await request(server)
      .get('/users?search=alice')
      .expect(200);

    // Should find Alice
    expect(response.body.data.some(user => 
      user.name.toLowerCase().includes('alice') ||
      user.email.toLowerCase().includes('alice')
    )).toBe(true);

    // Test with excessive length - should be truncated
    const longSearch = 'a'.repeat(100);
    response = await request(server)
      .get(`/users?search=${longSearch}`)
      .expect(200);

    // Should still work but with truncated search term
    expect(typeof response.body).toBe('object');
  });

  test('Non-existent route returns 404', async () => {
    const response = await request(server)
      .get('/nonexistent')
      .expect(404);

    expect(response.body).toHaveProperty('error', 'Not found');
  });
});

