// Secure application with proper error handling and input validation
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Data sanitization against XSS
app.use(mongoSanitize()); // Data sanitization against NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes',
});
app.use(limiter);

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any are expected
    const { format } = req.query;

    // Input validation
    if (format && !['json', 'text'].includes(format)) {
      return res.status(400).json({
        error: 'Invalid format parameter',
        message: 'Format must be either "json" or "text"'
      });
    }

    const responseData = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Conditional response formatting
    if (format === 'text') {
      res.type('text/plain').send(`Status: OK\nTimestamp: ${responseData.timestamp}`);
    } else {
      res.json(responseData);
    }
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to process health check request'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, sort } = req.query;

    // Input validation
    const validatedLimit = limit ? 
      Math.min(parseInt(limit, 10) || 10, 100) : 10; // Max 100

    const validatedOffset = offset ? 
      Math.max(parseInt(offset, 10) || 0, 0) : 0; // Min 0

    const validSortOptions = ['name', 'email', 'id'];
    const validatedSort = sort && validSortOptions.includes(sort) ? sort : 'id';

    // Sample data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Apply sorting
    let sortedUsers = [...users];
    if (validatedSort === 'name') {
      sortedUsers.sort((a, b) => a.name.localeCompare(b.name));
    } else if (validatedSort === 'email') {
      sortedUsers.sort((a, b) => a.email.localeCompare(b.email));
    } else {
      sortedUsers.sort((a, b) => a.id - b.id);
    }

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(
      validatedOffset, 
      validatedOffset + validatedLimit
    );

    res.json({
      count: paginatedUsers.length,
      total: users.length,
      limit: validatedLimit,
      offset: validatedOffset,
      users: paginatedUsers
    });
  } catch (error) {
    // Log error for debugging (in production, use proper logging library)
    console.error('Error in /users endpoint:', error);

    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging
  console.error('Global error handler:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Prepare error response
  const errorResponse = {
    error: err.message || 'Internal server error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  };

  res.status(statusCode).json(errorResponse);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = { app, server };

