app.get('/users', async (req, res, next) => {
  try {
    // Validate query parameters
    const { limit, offset, sort } = req.query;

    // Input validation
    if (limit && (isNaN(parseInt(limit)) || parseInt(limit) <= 0)) {
      return next(new AppError('Limit must be a positive number', 400));
    }

    if (offset && (isNaN(parseInt(offset)) || parseInt(offset) < 0)) {
      return next(new AppError('Offset must be a non-negative number', 400));
    }

    // Sanitize sort parameter
    const allowedSortFields = ['id', 'name', 'email'];
    if (sort && !allowedSortFields.includes(sort)) {
      return next(new AppError(`Sort field must be one of: ${allowedSortFields.join(', ')}`, 400));
    }

    // Simulate async database operation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const limitNum = parseInt(limit) || 10;
    const offsetNum = parseInt(offset) || 0;
    const paginatedUsers = users.slice(offsetNum, offsetNum + limitNum);

    // Apply sorting
    let sortedUsers = [...paginatedUsers];
    if (sort) {
      sortedUsers.sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });
    }

    res.status(200).json({
      status: 'success',
      results: sortedUsers.length,
      data: {
        users: sortedUsers
      }
    });
  } catch (err) {
    next(err); // Pass error to global error handler
  }
});

