const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json()); // Body parser

// Prevent NoSQL injection
app.use(mongoSanitize());

// Prevent XSS attacks
app.use(xss());

// Prevent HTTP parameter pollution
app.use(hpp());

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Health check endpoint with proper error handling
app.get('/health', (req, res, next) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error);
  }
});

// Users endpoint with input validation and error handling
app.get('/users', (req, res, next) => {
  try {
    // Validate query parameters if any exist
    const { limit, offset } = req.query;

    // Input validation
    if (limit !== undefined && (isNaN(parseInt(limit)) || parseInt(limit) < 1)) {
      return res.status(400).json({ 
        error: 'Invalid limit parameter', 
        message: 'Limit must be a positive integer' 
      });
    }

    if (offset !== undefined && (isNaN(parseInt(offset)) || parseInt(offset) < 0)) {
      return res.status(400).json({ 
        error: 'Invalid offset parameter', 
        message: 'Offset must be a non-negative integer' 
      });
    }

    // Sample data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination if specified
    const limitVal = limit ? parseInt(limit) : users.length;
    const offsetVal = offset ? parseInt(offset) : 0;

    const paginatedUsers = users.slice(offsetVal, offsetVal + limitVal);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: limitVal,
        offset: offsetVal,
        total: users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

// 404 handler
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Centralized error handling middleware
app.use((error, req, res, next) => {
  console.error('Error:', error); // Log error for debugging

  // Default error status
  const statusCode = error.statusCode || 500;

  // Don't leak stack trace in production
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' ? 
      'Internal Server Error' : 
      error.message || 'Unknown Error',
    ...(process.env.NODE_ENV !== 'production' && { stack: error.stack })
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

